let ι := ι;
let K := K;
let M := M;
let f := f;

let n : ℕ := fintype.card ι;

let V : Type u_3 := (ι → Dual K M);
let α : AddCommGroup V := addCommGroup.ofAddCommGroup V;
let β : Module K V := module.ofModule K V;
let γ : FiniteDimensional K V := finiteDimensional_pi' K ι (λ i, finiteDimensional_of_finite K M) ;

let g : V →₀ Dual K M := λ φ, (φ ∘ f).sum;

let h₁ : ∀ (i : ι), ∃ x, (f i) x ≠ 0 := h;
let h₂ : ∀ (x : M), ∃ i : ι, (f i) x = 0 :=
begin
  contrapositive,
  assume h: ∀ (x : M), ∀ i : ι, (f i) x ≠ 0,
  have h': ∀ (x : M), (g x) = 0,
  { intros x,
    rw linearMap.sum_apply,
    apply eq_zero_of_sum_eq_zero,
    intro i,
    exact h x i },
  have h'': g = 0,
  { convert h',
    ext φ,
    simp [g] },
  have h''': g = 0,
  { apply eq_zero_of_ker_eq_zero,
    apply finiteDimensional.injective_of_ker_eq_zero,
    apply finiteDimensional_of_finite K V,
    apply finiteDimensional_pi' K ι (λ i, finiteDimensional_of_finite K M) },
  contradiction
end;

let h₃ : g ≠ 0 := by contradiction h₂;

let h₄ : ∃ x, g x ≠ 0 := h₃;

let h₅ : ∃ x, ∀ i : ι, (f i) x ≠ 0 :=
begin
  let x : M := classical.some h₄,
  let h₆ : g x ≠ 0 := classical.some_spec h₄,
  have h₇ : ∀ i : ι, (f i) x ≠ 0,
  { intro i,
    rw linearMap.sum_apply,
    apply ne_zero_of_sum_ne_zero,
    intro j,
    exact (f i) x },
  exact ⟨x, h₇⟩
end;

exact h₅
